import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Entre na sua conta do Cloud","description":"","frontmatter":{"title":"Entre na sua conta do Cloud","docId":"user.cloud.account","translationKey":"user.cloud.account","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"898570b9036f2717f38381d86ec16968f768264097b84fb7524e87d15daeb961","translationRevision":"f69ac733ac75584284a39fe5523e36b8ccc09c4a3bc6f7b2d858052dcd2ebdb7","order":10},"headers":[],"relativePath":"pt/user/cloud/account.md","filePath":"pt/user/cloud/account.md","lastUpdated":1795735295000}`),a={name:`pt/user/cloud/account.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="sign-in-to-your-cloud-account" tabindex="-1">Entre na sua conta do Cloud <a class="header-anchor" href="#sign-in-to-your-cloud-account" aria-label="Permalink to “Entre na sua conta do Cloud”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Conecte o aplicativo de desktop ao serviço Cloud configurado para operações de catálogo e colaboração baseadas em conta. Você precisa de acesso à rede, um navegador do sistema e um armazenamento de credenciais do sistema operacional funcional. A edição local continua útil sem o Cloud; uma sessão do Cloud não autentica sua conexão com a LIVE do TikTok.</p><h2 id="sign-in-and-verify-identity" tabindex="-1">Entre e verifique a identidade <a class="header-anchor" href="#sign-in-and-verify-identity" aria-label="Permalink to “Entre e verifique a identidade”">​</a></h2><ol><li>Abra <strong>Settings → Account</strong>. Leia o estado atual antes de iniciar outro login.</li><li>Selecione <strong>Sign in</strong>. O desktop inicia um receptor local de retorno e abre a página de login configurada no navegador do sistema.</li><li>Conclua o fluxo de login do serviço e retorne ao TikTools. Se o navegador não abrir, use a URL de login mostrada pelo aplicativo para esta tentativa. Trate essa URL como privada e não a publique.</li><li>Aguarde o estado da conta indicar que a sessão está iniciada. Confirme o nome ou e-mail exibido antes de abrir um catálogo privado ou equipe.</li><li>Expanda os diagnósticos de Account se o status informar um erro. Use <strong>Cancel</strong> para abandonar uma tentativa inacabada em vez de deixar várias tentativas ativas.</li><li>Ao terminar em um computador compartilhado, selecione <strong>Sign out</strong> e verifique se o estado da conta mudou.</li></ol><p>O host nativo gerencia o token da sessão. Ele armazena credenciais pelo armazenamento de credenciais do sistema operacional e mantém apenas status não secreto no frontend. Não existe alternativa em arquivo de texto simples quando o armazenamento seguro está indisponível. Uma pasta de dados copiada não é uma sessão autenticada portátil.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>Login, restauração e saída nativos estão disponíveis em hosts compilados com autenticação do Cloud. Uma conta configurada pode ser restaurada ao reiniciar e revalidada com o serviço. Um host não configurado ou incompatível não se corrige fornecendo um cookie diferente do TikTok.</p><p>A disponibilidade do login do serviço e a aceitação real por provedor/plataforma dependem do serviço implantado e da sua máquina. A validação local não comprova que todas as rotas de login de produção funcionam.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Para uma tentativa cancelada ou expirada, inicie um login novo após fechar o anterior. Para erros de rede ou serviço, preserve o código de diagnóstico e tente novamente após a recuperação. Para um erro do armazenamento de credenciais, restaure a disponibilidade do armazenamento seguro do sistema operacional; não cole um token de portador nas configurações nem em uma mensagem de suporte. Consulte <a href="./changes.html">Changes</a> para sincronização explícita e <a href="./collaboration.html">colaboração</a> para concessões de acesso separadas.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes de operação”">​</a></h2><p>Sair apaga credenciais locais e limpa o contexto antes de tentar revogação remota de melhor esforço. A interface desconectada confirma remoção local, não revogação remota durante falha de rede. Use administração de sessões do serviço se disponível. Exporte Diagnostics antes de sair/trocar conta conhecida: esse histórico UI é apagado. Cookies TikTok e sessões de host remoto são identidades separadas.</p><h2 id="command-line-operations" tabindex="-1">Operações de linha de comando <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operações de linha de comando”">​</a></h2><p>Cada operação deste guia também está disponível na CLI — offline, scriptável e apta para agentes. As linhas de uso são sintaxe do parser e permanecem em inglês em todos os idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools cloud status</code></td><td>estado da conta cloud</td></tr><tr><td><code>tiktools cloud login</code></td><td>entrar pelo navegador do sistema</td></tr><tr><td><code>tiktools cloud logout</code></td><td>sair da conta <strong>destrutivo</strong></td></tr><tr><td><code>tiktools cloud restore</code></td><td>restaurar a sessão cloud</td></tr><tr><td><code>tiktools cloud backup create [--out FILE]</code></td><td>escrever um arquivo de backup portátil</td></tr><tr><td><code>tiktools cloud backup preview &lt;file&gt;</code></td><td>inspecionar um arquivo de backup</td></tr><tr><td><code>tiktools cloud backup restore &lt;file&gt; [--yes]</code></td><td>restaurar um arquivo de backup <strong>destrutivo</strong></td></tr></tbody></table><p>Consulte a <a href="./../../developer/cli.html">referência completa de comandos</a> para as convenções, a saída JSON e os marcadores de operações destrutivas.</p>`,17)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};